═══════════════════════════════════════════════════════════════════════// HANDLERS DE HERRAMIENTAS// ═══════════════════════════════════════════════════════════════════════════async function handleListDatasets(args: any) {    const limit = args.limit || 50;        try {        const result = await gremiusApi(`/api/data-sets?limit=${limit}`);        return {            content: [{                type: "text",                text: `📊 Datasets disponibles (${result.length}):\n\n${result.map((ds: any) =>                     `- **${ds.name}** (ID: ${ds.id})\n  Slug: ${ds.slug}\n  Descripción: ${ds.description || 'N/A'}`                ).join('\n\n')}`            }]        };    } catch (error: any) {        return {            content: [{                type: "text",                text: `❌ Error al listar datasets: ${error.message}`            }],            isError: true        };    }}async function handleSearchEntries(args: any) {    const { datasetId, query, semantic = false, limit = 10 } = args;        try {        let result;                if (semantic) {            // Búsqueda semántica/vectorial            result = await gremiusApi(`/api/datasets/${datasetId}/vector-search`, {                method: "POST",                body: JSON.stringify({ query, limit, threshold: 0.7 })            });        } else {            // Búsqueda de texto            result = await gremiusApi(`/api/data-sets/${datasetId}/entries?search=${encodeURIComponent(query)}&limit=${limit}`);        }                const entries = result.results || result;                if (entries.length === 0) {            return {                content: [{                    type: "text",                    text: `🔍 No se encontraron resultados para "${query}" en el dataset ${datasetId}`                }]            };        }                return {            content: [{                type: "text",                text: `🔍 Resultados para "${query}" (${entries.length} encontrados):\n\n${entries.map